#pragma once#include <rsuPaths.h>#include <stdio.h>template<size_t _S>void rsuINI_C( char * Name, char * Default, char (&Str)[_S] ){	strcpy_s( Str, Default );	char Path[1024];	sprintf_s ( Path, "%sPROP\\Properties.csv", rsuGetProjectPath() );	FILE * F = fopen ( Path, "rt" );  if( F == NULL )    return;	char Line[256];	// Секция	char * Sect = Line;	while( fgets( Line, _countof(Line)-1, F ))	{		char * P = strchr ( Sect, ';' );		if ( P == NULL )			continue;		char * Sect = P+4;		P = strchr ( Sect, ';' );		if ( P == NULL )			continue;		*P = 0;		if( strcmp( Sect, Name ) == 0 )		{			P += 4;			char *n = strchr(P, ';');			*n = 0;			strcpy_s( Str, P );			break;		}	}	fclose ( F );	return;}